print('--- avoid ---')
def seg_cd(p,q,c):
    vx,vy=q[0]-p[0],q[1]-p[1]; l2=vx*vx+vy*vy
    if l2<=EPS: return dist(p,c)
    t=max(0.0,min(1.0,((c[0]-p[0])*vx+(c[1]-p[1])*vy)/l2))
    return dist((p[0]+vx*t,p[1]+vy*t),c)

def fabrik_avoid(B,T,ls,C,R,tol=0.02,max_iter=128):
    n=len(ls); total=sum(ls)
    ba=math.atan2(T[1]-B[1],T[0]-B[0]) if dist(B,T)>EPS else 0.0
    P=[B]
    for j,l in enumerate(ls):
        if l<=EPS: P.append(P[-1])
        else:
            ang=ba+(0.35*j if dist(B,T)<total-1e-9 else 0.0)
            P.append(add(P[-1],mul((math.cos(ang),math.sin(ang)),l)))
    ba_v=(math.cos(ba),math.sin(ba)); perp=(-ba_v[1],ba_v[0])
    for it in range(1,max_iter+1):
        P[n]=T
        for i in range(n-1,-1,-1):
            d=dist(P[i+1],P[i])
            if d>EPS:
                P[i]=add(P[i+1],mul(norm(sub(P[i],P[i+1])),ls[i]))
        P[0]=B
        for i in range(0,n):
            d=dist(P[i+1],P[i])
            if d>EPS:
                P[i+1]=add(P[i],mul(norm(sub(P[i+1],P[i])),ls[i]))
        # 规避
        moved=False
        for j in range(1,n):
            if dist(P[j],C)<R:
                dd=dist(P[j],C)
                if dd<=EPS: P[j]=add(C,mul(perp,R*1.001))
                else: P[j]=add(C,mul(norm(sub(P[j],C)),R*1.001))
                moved=True
        for i in range(n):
            if seg_cd(P[i],P[i+1],C)>=R-1e-12: continue
            cands=[j for j in (i,i+1) if 0<j<n]
            if not cands: continue
            j=cands[0]
            if dist(P[j],C)<R*1.001:
                dd=dist(P[j],C)
                if dd<=EPS: P[j]=add(C,mul(perp,R*1.001))
                else: P[j]=add(C,mul(norm(sub(P[j],C)),R*1.001))
                moved=True
        if moved:
            # 重新约束骨长（双向各一遍）
            P[0]=B
            for i in range(n):
                d=dist(P[i+1],P[i])
                if d>EPS: P[i+1]=add(P[i],mul(norm(sub(P[i+1],P[i])),ls[i]))
        ok = dist(P[n],T)<=tol and all(seg_cd(P[i],P[i+1],C)>=R-1e-9 for i in range(n))
        if ok: return P,it,dist(P[n],T),False
    return P,max_iter,dist(P[n],T),True

