        if best_s!=0.0:
            c,si=math.cos(best_s),math.sin(best_s)
            for k in range(i+1,n+1):
                dx,dy=P[k][0]-pivot[0],P[k][1]-pivot[1]
                P[k]=(pivot[0]+c*dx-si*dy,pivot[1]+si*dx+c*dy)

